// BFS：每一層把單字的每個位置換成 a~z，找出字典中的下一個單字
// 時間複雜度: O(N · L · 26)，空間複雜度: O(N · L)
function ladderLength(beginWord, endWord, wordList) {
    const words = new Set(wordList);
    if (!words.has(endWord))
        return 0;
    let queue = [beginWord];
    words.delete(beginWord);
    for (let steps = 1; queue.length; steps++) {
        const next = [];
        for (const word of queue) {
            if (word === endWord)
                return steps;
            for (let i = 0; i < word.length; i++) {
                for (let c = 97; c <= 122; c++) {
                    const cand = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1);
                    if (words.has(cand)) {
                        words.delete(cand); // 刪除即代表已訪問
                        next.push(cand);
                    }
                }
            }
        }
        queue = next;
    }
    return 0;
}

