#include <string>
#include <vector>
#include <unordered_set>
#include <queue>

class Solution {
public:
    /**
     * 方法：BFS
     * 時間複雜度: O(M^2 * N)
     * 空間複雜度: O(N)
     */
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        // 將 wordList 轉為 set
        unordered_set<string> word_set(wordList.begin(), wordList.end());

        // endWord 必須在 wordList 中
        if (word_set.find(endWord) == word_set.end()) {
            return 0;
        }

        // BFS 佇列：(當前單詞, 步數)
        queue<pair<string, int>> q;
        q.push({beginWord, 1});

        unordered_set<string> visited;
        visited.insert(beginWord);

        while (!q.empty()) {
            auto [current_word, steps] = q.front();
            q.pop();

            // 嘗試改變每個位置的字母
            for (int i = 0; i < current_word.length(); i++) {
                string new_word = current_word;

                // 嘗試 a-z
                for (char c = 'a'; c <= 'z'; c++) {
                    new_word[i] = c;

                    // 找到目標
                    if (new_word == endWord) {
                        return steps + 1;
                    }

                    // 新單詞在字典中且未訪問
                    if (word_set.count(new_word) && !visited.count(new_word)) {
                        visited.insert(new_word);
                        q.push({new_word, steps + 1});
                    }
                }
            }
        }

        // 無法到達
        return 0;
    }
};

