// BFS：把字典索引放進佇列，相差恰好一個字元的單字互為鄰居
// 時間複雜度: O(N² · L)，空間複雜度: O(N)
static bool oneDiff(const char* a, const char* b) {
    int diff = 0;
    for (; *a; a++, b++) {
        if (*a != *b && ++diff > 1) return false;
    }
    return diff == 1;
}

int ladderLength(char* beginWord, char* endWord, char** wordList, int wordListSize) {
    int n = wordListSize, target = -1;
    for (int i = 0; i < n; i++) if (strcmp(wordList[i], endWord) == 0) target = i;
    if (target == -1) return 0;

    bool* visited = calloc(n, sizeof(bool));
    int* queue = malloc(sizeof(int) * n);
    int head = 0, tail = 0;
    for (int i = 0; i < n; i++) {                 // 第一層：與 beginWord 差一個字元的單字
        if (oneDiff(beginWord, wordList[i])) {
            visited[i] = true;
            queue[tail++] = i;
        }
    }

    int ans = 0;
    for (int steps = 2; head < tail && !ans; steps++) {
        int levelEnd = tail;
        while (head < levelEnd && !ans) {
            int cur = queue[head++];
            if (cur == target) { ans = steps; break; }
            for (int i = 0; i < n; i++) {
                if (!visited[i] && oneDiff(wordList[cur], wordList[i])) {
                    visited[i] = true;
                    queue[tail++] = i;
                }
            }
        }
    }
    free(visited);
    free(queue);
    return ans;
}

